import { Html, OrbitControls, useTexture } from '@react-three/drei';
import { Canvas } from '@react-three/fiber';
import { Suspense, useEffect, useMemo } from 'react';
import { BackSide, MathUtils, SRGBColorSpace } from 'three';
import type { PanoramaConfig } from '../../config/schema';
import { resolveAssetUrl } from '../../config/loadConfig';
import { useWebGLContextRecovery } from '../../shared/useWebGLContextRecovery';

/** 球体贴图只处理站内全景图；外部嵌入点位走 PanoramaPage 的 iframe 分支。 */
export type PanoramaScenePoint = PanoramaConfig & { image: string };

function hotspotPosition(yaw: number, pitch: number, radius = 18): [number, number, number] {
  const yawRadians = MathUtils.degToRad(yaw);
  const pitchRadians = MathUtils.degToRad(pitch);
  return [
    radius * Math.cos(pitchRadians) * Math.sin(yawRadians),
    radius * Math.sin(pitchRadians),
    -radius * Math.cos(pitchRadians) * Math.cos(yawRadians),
  ];
}

function PanoramaContent({ point, onHotspot }: { point: PanoramaScenePoint; onHotspot(id: string): void }) {
  const sourceTexture = useTexture(resolveAssetUrl(point.image));
  const texture = useMemo(() => sourceTexture.clone(), [sourceTexture]);
  texture.colorSpace = SRGBColorSpace;
  useEffect(() => () => texture.dispose(), [texture]);
  return (
    <>
      <mesh><sphereGeometry args={[20, 64, 40]} /><meshBasicMaterial map={texture} side={BackSide} /></mesh>
      {point.hotspots.map(hotspot => (
        <Html key={hotspot.id} position={hotspotPosition(hotspot.yaw, hotspot.pitch)} center transform distanceFactor={10}>
          <button type="button" className="panorama-hotspot" onClick={() => onHotspot(hotspot.targetId)}><i /><span>{hotspot.label}</span></button>
        </Html>
      ))}
      <OrbitControls enablePan={false} enableZoom={false} rotateSpeed={-0.35} target={[0, 0, -1]} minPolarAngle={MathUtils.degToRad(20)} maxPolarAngle={MathUtils.degToRad(160)} />
    </>
  );
}

export function PanoramaScene({ point, onHotspot }: { point: PanoramaScenePoint; onHotspot(id: string): void }) {
  const { generation, onCreated, lost } = useWebGLContextRecovery();
  return (
    <Canvas key={generation} onCreated={onCreated} dpr={[1, 1.5]} camera={{ position: [0, 0, 0.01], fov: 65 }} gl={{ antialias: true, alpha: false }} style={{ opacity: lost ? 0 : 1 }}>
      <Suspense fallback={<Html center><span className="panorama-loading">正在加载全景场景</span></Html>}>
        <PanoramaContent point={point} onHotspot={onHotspot} />
      </Suspense>
    </Canvas>
  );
}
