import { useCallback, useState } from 'react';
import type { RootState } from '@react-three/fiber';

/**
 * Handles a lost WebGL context without causing a remount storm.
 *
 * On `webglcontextlost` we call `preventDefault()` (so the browser may restore
 * the context) and hide the canvas — a lost context is painted white by some
 * mobile browsers, so hiding it avoids the white flash. We then remount on
 * `webglcontextrestored`, exactly like the standard pattern. A short fallback
 * timer recreates the canvas if the browser never restores, so the model still
 * recovers without repeatedly remounting on every transient loss.
 */
export function useWebGLContextRecovery() {
  const [generation, setGeneration] = useState(0);
  const [lost, setLost] = useState(false);

  const onCreated = useCallback(({ gl }: RootState) => {
    const canvas = gl.domElement;
    let fallbackTimer: number | null = null;

    const handleLost = (event: Event) => {
      event.preventDefault();
      setLost(true);
      if (fallbackTimer === null) {
        fallbackTimer = window.setTimeout(() => {
          fallbackTimer = null;
          setLost(false);
          setGeneration(value => value + 1);
        }, 400);
      }
    };

    const handleRestored = () => {
      if (fallbackTimer !== null) {
        window.clearTimeout(fallbackTimer);
        fallbackTimer = null;
      }
      setLost(false);
      setGeneration(value => value + 1);
    };

    canvas.addEventListener('webglcontextlost', handleLost);
    canvas.addEventListener('webglcontextrestored', handleRestored);
  }, []);

  return { generation, onCreated, lost };
}
