import { Info, LoaderCircle, Map, RotateCcw } from 'lucide-react';
import { type ComponentType, useEffect, useState } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { resolveAssetUrl } from '../../config/loadConfig';
import { hasPanoramaImage, isEmbeddedPanorama, type PanoramaConfig } from '../../config/schema';
import { hasWebGLSupport } from '../../shared/webgl';
import { getAdjacentPanoramaIds } from './panoramaGraph';
import { PanoramaScene, type PanoramaScenePoint } from './PanoramaScene';
import { preloadImage } from './preloadPanoramas';
import './panorama.css';

export interface PanoramaSceneProps {
  point: PanoramaScenePoint;
  onHotspot(id: string): void;
}

/**
 * 外部全景作品（如 720yun）：直接用 iframe 呈现对方的播放器。
 * 内容由第三方维护，运行期必须联网；嵌入模式通常拿不到全屏/VR/陀螺仪。
 */
function EmbeddedPanorama({ point }: { point: PanoramaConfig & { embedUrl: string } }) {
  const [attempt, setAttempt] = useState(0);
  const [status, setStatus] = useState<'loading' | 'loaded' | 'failed'>('loading');

  useEffect(() => {
    if (status !== 'loading') return;
    const timer = window.setTimeout(() => {
      // 某些内置浏览器第一次嵌入会停在 about:blank，重新挂载 iframe 可恢复。
      if (attempt === 0) setAttempt(1);
      else setStatus('failed');
    }, 12_000);
    return () => window.clearTimeout(timer);
  }, [attempt, status]);

  const retry = () => {
    setStatus('loading');
    setAttempt(value => value + 1);
  };

  return (
    <>
      <iframe
        key={attempt}
        className="panorama-embed"
        src={point.embedUrl}
        title={point.name}
        /* 720yun 官方提供的嵌入地址；只申请全屏权限。 */
        allow="fullscreen"
        allowFullScreen
        referrerPolicy="strict-origin-when-cross-origin"
        onLoad={event => {
          try {
            const url = event.currentTarget.contentWindow?.location.href;
            if (!url || url === 'about:blank') return;
          } catch {
            // 跨域访问被拒绝，说明 iframe 已从初始空白页进入第三方文档。
          }
          setStatus('loaded');
        }}
        onError={() => {
          if (attempt === 0) setAttempt(1);
          else setStatus('failed');
        }}
      />
      {status !== 'loaded' && (
        <div className="panorama-embed-status" role={status === 'failed' ? 'alert' : 'status'}>
          {status === 'loading'
            ? <><LoaderCircle className="panorama-embed-spinner" /><span>正在加载漫游</span></>
            : <>
                <span>漫游加载失败</span>
                <button type="button" onClick={retry}>重试加载</button>
                <a href={point.embedUrl} target="_blank" rel="noopener noreferrer">单独打开漫游</a>
              </>}
        </div>
      )}
    </>
  );
}

export function PanoramaPage({ SceneComponent = PanoramaScene, imageLoader = preloadImage, supportsWebGL = hasWebGLSupport, onExit, active = true }: {
  SceneComponent?: ComponentType<PanoramaSceneProps>;
  imageLoader?: (url: string) => Promise<void>;
  supportsWebGL?: () => boolean;
  /**
   * 作为地图页的全屏层渲染时传入：点「在地图查看位置」就是**收起这一层**，
   * 底下的地图不重新加载、视野也不丢。不传则是独立页面，走原来的路由跳转。
   */
  onExit?: () => void;
  /**
   * 本页当前是否显示。全景页在「全景漫游」常驻槽位里：切到别的栏目只是加 hidden、不卸载，
   * 但嵌入的是第三方播放器（跨域 iframe 一旦挂上就会继续跑，可能还有声音，没法暂停），
   * 所以隐藏时整页不渲染内容；返回时重新挂载（对外部内容本来也要重新拉一次）。
   */
  active?: boolean;
}) {
  const { pointId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { config, repository } = useMuseumConfig();
  const point = repository.getPanorama(pointId ?? '') ?? config.panoramas[0];
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sceneKey, setSceneKey] = useState(0);
  const [webglAvailable] = useState(() => supportsWebGL());
  /**
   * 从地图标记「推进来」时收尾：`?enter=1` 由地图页在跳转时带上，
   * 幕布从全黑淡出，接上地图那边的放大+压暗，整体是一次连续推进。
   */
  const [entering, setEntering] = useState(() => new URLSearchParams(location.search).has('enter'));

  useEffect(() => {
    if (!entering) return;
    const timer = window.setTimeout(() => setEntering(false), 520);
    return () => window.clearTimeout(timer);
  }, [entering]);

  useEffect(() => {
    if (!point) return;
    // 只预加载站内全景图；外部嵌入点位由对方自己加载。
    for (const id of getAdjacentPanoramaIds(point)) {
      const adjacent = repository.getPanorama(id);
      if (adjacent && hasPanoramaImage(adjacent)) {
        void imageLoader(resolveAssetUrl(adjacent.image)).catch(() => undefined);
      }
    }
  }, [imageLoader, point, repository]);

  if (!point) return <section className="status-panel" role="alert">没有可用的全景点位</section>;
  // 被常驻槽位隐藏时不渲染内容（原因见 active 的注释）：第三方嵌入页必须卸掉，
  // 站内球体贴图在返回时会重新挂载，图片本身走浏览器缓存。
  if (!active) return null;

  const embedded = isEmbeddedPanorama(point);

  const changePoint = async (targetId: string) => {
    const target = repository.getPanorama(targetId);
    if (!target || busy) return;
    setBusy(true);
    setError(null);
    try {
      if (hasPanoramaImage(target)) await imageLoader(resolveAssetUrl(target.image));
      navigate(`/panorama/${target.id}`);
      setSceneKey(value => value + 1);
    } catch {
      setError(`全景加载失败，仍停留在${point.name}`);
    } finally {
      setBusy(false);
    }
  };

  return (
    <section className={entering ? 'panorama-page is-entering' : 'panorama-page'}>
      <div className={embedded ? 'panorama-stage is-embedded' : 'panorama-stage'}>
        {embedded
          ? <EmbeddedPanorama key={`${point.id}-${sceneKey}`} point={point} />
          : hasPanoramaImage(point)
            ? webglAvailable
              ? <SceneComponent key={`${point.id}-${sceneKey}`} point={point} onHotspot={changePoint} />
              : <div className="webgl-fallback panorama-static"><img src={resolveAssetUrl(point.image)} alt={`${point.name}静态全景`} /><div aria-label="全景目的地">{point.hotspots.map(hotspot => <button type="button" key={hotspot.id} onClick={() => void changePoint(hotspot.targetId)}>{hotspot.label}</button>)}</div></div>
            : null}
        {!embedded && <div className="panorama-brand"><small>360° TOUR</small><h1>{point.name}</h1></div>}
        <div className="panorama-tools">
          <button
            type="button"
            className="panorama-map"
            aria-label="在地图查看位置"
            onClick={() => {
              // 嵌在地图页里时只是收起这一层；独立打开时才跳回地图。
              if (onExit) { onExit(); return; }
              const mapId = repository.findMapIdForPanorama(point.id) ?? repository.getRootMap()?.id;
              navigate(mapId ? `/map/${mapId}?focus=${point.id}` : '/map');
            }}
          ><Map /></button>
          {embedded && <button type="button" className="panorama-reset" aria-label="重新加载漫游" onClick={() => setSceneKey(value => value + 1)}><RotateCcw /></button>}
          {!embedded && webglAvailable && <button type="button" className="panorama-reset" aria-label="复位全景视角" onClick={() => setSceneKey(value => value + 1)}><RotateCcw /></button>}
        </div>
        {busy && <div className="panorama-busy" role="status"><LoaderCircle />正在加载下一点位</div>}
      </div>
      {/* 外部作品嵌入时不显示信息面板：漫游本身就是内容，不需要额外的文字提示。 */}
      {!embedded && (
        <section className="panorama-info">
          <div>
            <Info />
            <p>{point.description}</p>
          </div>
          <nav aria-label="全景点位导航">{point.hotspots.map(hotspot => {
            const target = repository.getPanorama(hotspot.targetId);
            return <button type="button" key={hotspot.id} aria-label={`导航至${target?.name ?? hotspot.label}`} onClick={() => void changePoint(hotspot.targetId)}>{target?.name ?? hotspot.label}</button>;
          })}</nav>
        </section>
      )}
      {error && <div className="panorama-error" role="alert">{error}</div>}
    </section>
  );
}
