export type ImageFactory = () => HTMLImageElement;

export function preloadImage(url: string, imageFactory: ImageFactory = () => new Image()) {
  return new Promise<void>((resolve, reject) => {
    const image = imageFactory();
    image.onload = () => resolve();
    image.onerror = () => reject(new Error(`全景加载失败：${url}`));
    image.src = url;
  });
}
